const DEX={bulbasaur:{name:'Bulbasaur',id:1,type:'Planta / Veneno',emoji:'🌱'},charmander:{name:'Charmander',id:4,type:'Fogo',emoji:'🔥'},squirtle:{name:'Squirtle',id:7,type:'Água',emoji:'💧'},pidgey:{name:'Pidgey',id:16,type:'Normal / Voador',emoji:'🪶'},rattata:{name:'Rattata',id:19,type:'Normal',emoji:'🐾'},pikachu:{name:'Pikachu',id:25,type:'Elétrico',emoji:'⚡'},oddish:{name:'Oddish',id:43,type:'Planta / Veneno',emoji:'🌿'},growlithe:{name:'Growlithe',id:58,type:'Fogo',emoji:'🔥'},psyduck:{name:'Psyduck',id:54,type:'Água',emoji:'💧'},eevee:{name:'Eevee',id:133,type:'Normal',emoji:'✨'}};
const ITEMS={leaf:{name:'Capa de folhas',icon:'🍃',description:'Uma capa tecida com folhas resistentes. +5 de energia máxima.',effect:'Energia máx. +5',visual:'🍃'},flower:{name:'Coroa silvestre',icon:'🌼',description:'Flores aromáticas que afastam o cansaço. +2 de ataque.',effect:'Ataque +2',visual:'🌼'},scarf:{name:'Cachecol de brasa',icon:'🧣',description:'Aquece até nos dias mais frios. +3 de ataque.',effect:'Ataque +3',visual:'🧣'},glasses:{name:'Óculos de explorador',icon:'🥽',description:'Lentes para enxergar trilhas escondidas. +2 de ataque.',effect:'Ataque +2',visual:'🥽'},medal:{name:'Medalha trovão',icon:'⚡',description:'Uma medalha que vibra com energia. +3 de ataque.',effect:'Ataque +3',visual:'⚡'},berry:{name:'Baga Oran',icon:'🫐',description:'Recupera 35 pontos de energia durante uma batalha.',effect:'Cura 35 de energia',visual:'🫐'}};
const fresh=()=>({starter:null,team:[],active:null,level:1,xp:0,hp:100,maxHp:100,berries:12,explores:0,quest:0,bag:['leaf','flower','scarf','glasses','medal','berry'],equipped:{},journal:[],sound:false});
