 $('#teamEmpty').style.display=state.team.length>1?'none':'block';$('#partnerCount').textContent=String(state.team.length).padStart(2,'0');$('.team-count').textContent=state.team.length;$('.bag-count').textContent=state.bag.length;
 $('#statLevel').textContent=String(state.level).padStart(2,'0');$('#statXp').textContent=`${state.xp} / ${state.level*30}`;$('#xpFill').style.width=`${Math.min(100,state.xp/(state.level*30)*100)}%`;$('#statHp').textContent=`${state.hp} / ${state.maxHp}`;$('#hpFill').style.width=`${hpBar(state.hp,state.maxHp)}%`;$('#berries').textContent=state.berries;$('#exploreCount').textContent=String(Math.max(1,state.explores+1)).padStart(2,'0');
 let q=Math.min(100,state.quest/3*100);$('.quest-progress i').style.width=`${q}%`;$('.quest-status span').textContent=`${Math.min(3,state.quest)}/3`;$('.quest-status').firstChild.textContent=state.quest>=3?'A trilha está segura ':state.quest?'Investigue a trilha ':'Investigue a trilha ';
}
function modal(title,subtitle,body,buttons=''){modalRoot.innerHTML=`<div class="modal" role="dialog" aria-modal="true"><div class="modal-head"><div><span class="eyebrow">POKÉRAMPAGE · FLORESTA DE VERIDIANA</span><h2>${title}</h2><p>${subtitle}</p></div><button class="close-modal" aria-label="Fechar">×</button></div>${body}${buttons?`<div class="modal-actions">${buttons}</div>`:''}</div>`;$('.close-modal').onclick=()=>modalRoot.innerHTML='';modalRoot.onclick=e=>{if(e.target===modalRoot)modalRoot.innerHTML='';};}
function startGame(key){state.starter=key;state.active=key;state.team=[{key,level:1}];state.maxHp=100;state.hp=100;addJournal(`Sua jornada começou com ${DEX[key].name}.`);save();modalRoot.innerHTML='';toast(`${DEX[key].name} está pronto para a aventura!`)}
function showStarter(){modal('Quem será você?','Escolha seu Pokémon para começar a aventura. Você poderá libertar mais parceiros pelo caminho.',`<div class="starter-grid">${['bulbasaur','charmander','squirtle'].map(k=>`<button class="starter-card" data-starter="${k}">${sprite(k)}<b>${DEX[k].name}</b><small>Pokémon ${DEX[k].type}</small><span class="type-tag">Nº ${String(DEX[k].id).padStart(3,'0')} na Pokédex</span></button>`).join('')}</div>`);document.querySelectorAll('[data-starter]').forEach(b=>b.onclick=()=>startGame(b.dataset.starter));$('.close-modal').style.display='none';}
function toast(msg){let t=$('#eventToast');t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2500)}
function explore(){if(state.hp<=0){modal('Seu Pokémon precisa descansar','A aventura pode esperar um pouco.',`<p class="battle-message">Recupere energia antes de continuar pela trilha.</p>`,`<button class="btn" id="modalRest">Descansar</button>`);$('#modalRest').onclick=()=>rest();return}state.explores++;state.quest=Math.min(3,state.quest+1);let n=state.explores;$('#scene').classList.add('feed-fade');setTimeout(()=>$('#scene').classList.remove('feed-fade'),500);
 if(n===1){addJournal('Pegadas estranhas levam a um Pokémon selvagem.');startBattle('pidgey');return}
 if(n===2&&!state.team.some(x=>x.key==='pikachu')){addJournal('Você encontrou uma jaula escondida na mata.');showRescue('pikachu');return}
 if(n===4&&!state.team.some(x=>x.key==='oddish')){addJournal('Um Oddish está preso perto de um riacho.');showRescue('oddish');return}
 if(n%3===0){const found=['growlithe','psyduck','rattata'].filter(x=>!state.team.some(p=>p.key===x));let k=found[Math.floor(Math.random()*found.length)]||'rattata';addJournal(`Um ${DEX[k].name} apareceu na trilha.`);startBattle(k);return}
 if(n===3){let b=Math.random()<.6?'glasses':'berry';if(b==='berry')state.berries+=2;else if(!state.bag.includes(b))state.bag.push(b);state.xp+=12;addJournal(`Você investigou a trilha e encontrou ${b==='berry'?'duas bagas Oran':'Óculos de explorador'}.`);levelCheck();save();modal('Um achado na trilha','Entre as samambaias, algo brilhou ao sol.',`<div class="item-card"><div class="item-art">${ITEMS[b].icon}</div><div><b>${b==='berry'?'Duas bagas Oran':ITEMS[b].name}</b><small>${b==='berry'?'Uma pausa saborosa. +2 bagas':'Um item para equipar e mudar o visual.'}</small></div></div><p class="battle-message">Você ganhou 12 XP por investigar a floresta.</p>`,`<button class="btn" id="continueBtn">Continuar</button>`);$('#continueBtn').onclick=()=>modalRoot.innerHTML='';return}
 let berries=2+Math.floor(Math.random()*3);state.berries+=berries;state.hp=Math.min(state.maxHp,state.hp+8);state.xp+=8;addJournal(`Uma caminhada tranquila: +${berries} bagas e 8 XP.`);levelCheck();save();toast(`Trilha tranquila! +${berries} bagas · +8 XP`)}
function showRescue(key){modal('Um pedido de ajuda!','Você encontrou uma jaula de madeira escondida entre as raízes.',`<div class="choice-card">${sprite(key)}<span><b>${DEX[key].name} · Nº ${String(DEX[key].id).padStart(3,'0')}</b><small>${DEX[key].type} · Está assustado, mas parece bem.</small></span></div><p class="battle-message">A fechadura está enferrujada. Quebre-a para libertar o Pokémon e ganhe um novo parceiro!</p>`,`<button class="btn" id="freeBtn">⛓ Libertar ${DEX[key].name}</button><button class="btn secondary" id="laterBtn">Voltar depois</button>`);$('#freeBtn').onclick=()=>{state.team.push({key,level:1});state.quest=Math.min(3,state.quest+1);state.xp+=16;state.hp=Math.min(state.maxHp,state.hp+10);addJournal(`${DEX[key].name} foi libertado e se juntou à equipe!`);levelCheck();save();modalRoot.innerHTML='';toast(`${DEX[key].name} se juntou à sua equipe!`)};$('#laterBtn').onclick=()=>modalRoot.innerHTML=''}
let battle;
function startBattle(key){battle={key,enemyMax:34+state.level*3,enemyHp:34+state.level*3,turn:true,done:false,message:`Um ${DEX[key].name} selvagem apareceu! O que ${DEX[state.active].name} fará?`};renderBattle()}
function renderBattle(){if(!battle)return;let p=current();let buttons=battle.done?`<button class="btn" id="battleClose">Continuar</button>`:`<button class="btn" id="attackBtn">✦ Investida</button><button class="btn" id="skillBtn">❋ Golpe especial</button><button class="btn secondary" id="berryBtn">🫐 Usar baga (${state.berries})</button><button class="btn secondary" id="runBtn">Correr</button>`;
 modal(`Encontro selvagem`,`Uma batalha começou na trilha!`,`<div class="battle-arena">${sprite(p.key,'battle-pokemon hero')}${sprite(battle.key,'battle-pokemon enemy')}<div class="battle-name"><b>${DEX[p.key].name} · Nv. ${state.level}</b><small>♥ ${state.hp}/${state.maxHp}</small></div><div class="battle-name enemy-name"><b>${DEX[battle.key].name} selvagem</b><small>♥ ${battle.enemyHp}/${battle.enemyMax}</small></div></div><div class="battle-message" id="battleMessage">${battle.message}</div><div class="battle-controls">${buttons}</div>`);
 if(battle.done){$('#battleClose').onclick=()=>{modalRoot.innerHTML='';battle=null;};return}$('#attackBtn').onclick=()=>battleTurn(false);$('#skillBtn').onclick=()=>battleTurn(true);$('#berryBtn').onclick=()=>{if(state.berries<1){battle.message='Você não tem bagas!';renderBattle();return}if(state.hp>=state.maxHp){battle.message='Sua energia já está cheia.';renderBattle();return}state.berries--;state.hp=Math.min(state.maxHp,state.hp+35);battle.message=`${DEX[state.active].name} comeu uma Baga Oran e recuperou energia!`;enemyTurn()};$('#runBtn').onclick=()=>{battle.done=true;battle.message='Você recuou com segurança. A floresta ainda espera por você.';addJournal(`Você evitou a batalha contra ${DEX[battle.key].name}.`);save();renderBattle()}}
function battleTurn(special){if(!battle||battle.done)return;let p=current();let base=(4+state.level*2)+(ITEMS[state.equipped[p.key]]?.effect.includes('Ataque')?3:0);let dmg=special?base+8+Math.floor(Math.random()*5):base+Math.floor(Math.random()*5);battle.enemyHp=Math.max(0,battle.enemyHp-dmg);if(battle.enemyHp<=0){battle.done=true;let reward=18+state.level*3;state.xp+=reward;state.berries+=3;state.hp=Math.min(state.maxHp,state.hp+8);state.quest=Math.min(3,state.quest+1);addJournal(`Vitória contra ${DEX[battle.key].name}: +${reward} XP e 3 bagas.`);let intro=`${DEX[p.key].name} causou ${dmg} de dano. ${DEX[battle.key].name} fugiu! Você ganhou ${reward} XP e 3 bagas.`;if(Math.random()<.4){let item=['leaf','flower','scarf','glasses','medal'].find(x=>!state.bag.includes(x));if(item){state.bag.push(item);intro+=` Encontrou ${ITEMS[item].name}!`;addJournal(`Encontrou ${ITEMS[item].name} após a batalha.`)}}levelCheck();battle.message=intro;save();renderBattle();return}battle.message=`${special?'Golpe especial':'Investida'}! ${DEX[p.key].name} causou ${dmg} de dano.`;enemyTurn()}
