const fresh=()=>({starter:null,team:[],active:null,level:1,xp:0,hp:100,maxHp:100,berries:12,explores:0,quest:0,bossDefeated:false,bag:['leaf','flower','scarf','glasses','medal','berry'],equipped:{},journal:[],sound:false,zone:0});
let state;try{const old=JSON.parse(localStorage.getItem('pokerampage-save')||'null');state={...fresh(),...(old||{})};if(!Array.isArray(state.team))state.team=[];if(!Array.isArray(state.bag))state.bag=fresh().bag.slice();if(!state.equipped||typeof state.equipped!=='object')state.equipped={};if(!Array.isArray(state.journal))state.journal=[];state.team.forEach(p=>{p.level=p.level||state.level||1});state.zone=Math.min(2,Math.max(0,Number(state.zone)||0));}catch{state=fresh()}
const $=s=>document.querySelector(s),modalRoot=$('#modalRoot');let battle=null;
function save(){localStorage.setItem('pokerampage-save',JSON.stringify(state));render()}
function sprite(key,cls=''){let p=DEX[key];return p?`<img class="${cls}" src="https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/${p.id}.png" alt="${p.name}" onerror="this.style.display='none'">`:''}
function portrait(key,cls='',equipped=state.equipped[key]){const item=ITEMS[equipped],wear=item?.wear;return `<div class="pokemon-portrait ${cls}">${sprite(key)}${wear?`<span class="wearable wear-${wear}" role="img" aria-label="${item.visual}"></span>`:''}</div>`}
function addJournal(text){state.journal.unshift({text,time:new Date().toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})});if(state.journal.length>30)state.journal.pop()}
function hpBar(hp,max){return Math.max(0,Math.min(100,hp/max*100))}
function current(){return state.team.find(p=>p.key===state.active)}
function itemStats(key){return ITEMS[state.equipped[key]]||{attack:0,defense:0,maxHp:0}}
function syncMaxHp(key=state.active){const max=100+(state.level-1)*12+(itemStats(key).maxHp||0);if(key===state.active){state.maxHp=max;state.hp=Math.min(state.hp,max)}}
function zoneForLevel(){return state.level>=7?2:state.level>=4?1:0}
function render(){if(!state.starter)return;let p=current();if(!p)return;state.zone=zoneForLevel();syncMaxHp(p.key);
 $('#heroPokemon').innerHTML=portrait(p.key,'scene-portrait');
 $('#activePartner').innerHTML=`<div class="partner-main"><div class="partner-sprite">${portrait(p.key,'small')}</div><div class="partner-info"><span class="eyebrow">${p.key===state.starter?'SEU POKÉMON':'PARCEIRO'}</span><strong>${DEX[p.key].name}</strong><small>${DEX[p.key].type}</small></div></div><div class="partner-hp"><div><span>Energia</span><b>${state.hp} / ${state.maxHp}</b></div><div class="hp-track"><i style="width:${hpBar(state.hp,state.maxHp)}%"></i></div></div>`;
 $('#teamList').innerHTML=state.team.filter(x=>x.key!==state.active).map(x=>`<div class="team-row" data-switch="${x.key}">${portrait(x.key,'small')}<span><b>${DEX[x.key].name}</b><small>Nível ${x.level||1} · ${DEX[x.key].type}</small></span><span class="switch-label">JOGAR →</span></div>`).join('');
 $('#teamEmpty').style.display=state.team.length>1?'none':'block';$('#partnerCount').textContent=String(state.team.length).padStart(2,'0');$('.team-count').textContent=state.team.length;$('.bag-count').textContent=state.bag.length;
 $('#statLevel').textContent=String(state.level).padStart(2,'0');$('#statXp').textContent=`${state.xp} / ${state.level*42}`;$('#xpFill').style.width=`${Math.min(100,state.xp/(state.level*42)*100)}%`;$('#statHp').textContent=`${state.hp} / ${state.maxHp}`;$('#hpFill').style.width=`${hpBar(state.hp,state.maxHp)}%`;$('#berries').textContent=state.berries;$('#exploreCount').textContent=String(Math.max(1,state.explores+1)).padStart(2,'0');
 const zone=ZONES[state.zone];$('.scene-label b').textContent=zone.name;$('.scene-label small').textContent=`Rota 0${state.zone+1} · ${zone.region}`;$('.welcome-row .eyebrow').innerHTML=`CAPÍTULO I <i>·</i> ROTA 0${state.zone+1}`;$('#threatLevel').textContent=zone.threat;
 const clues=Math.min(3,state.quest),q=clues/3*100;$('.quest-progress i').style.width=`${q}%`;$('.quest-status span').textContent=state.bossDefeated?'CONCLUÍDA':`${clues}/3 pistas`;$('.quest-status b').textContent=state.bossDefeated?'MISSÃO CONCLUÍDA':'EM ANDAMENTO';$('#objectiveText').textContent=state.bossDefeated?'A mata está mais segura. Explore novas rotas e faça aliados.':clues>=3?'Enfrente o caçador que ronda a clareira.':`Investigue a trilha e encontre pistas (${clues}/3).`;
}
function modal(title,subtitle,body,buttons=''){modalRoot.innerHTML=`<div class="modal" role="dialog" aria-modal="true"><div class="modal-head"><div><span class="eyebrow">POKÉRAMPAGE · CRÔNICAS DA FLORESTA</span><h2>${title}</h2><p>${subtitle}</p></div><button class="close-modal" aria-label="Fechar">×</button></div>${body}${buttons?`<div class="modal-actions">${buttons}</div>`:''}</div>`;$('.close-modal').onclick=()=>modalRoot.innerHTML='';modalRoot.onclick=e=>{if(e.target===modalRoot)modalRoot.innerHTML='';};}
function startGame(key){state.starter=key;state.active=key;state.team=[{key,level:1}];state.level=1;state.xp=0;state.maxHp=100;state.hp=100;addJournal(`Sua jornada começou com ${DEX[key].name}.`);save();modalRoot.innerHTML='';toast(`${DEX[key].name} está pronto para a aventura!`)}
function showStarter(){modal('Escolha seu primeiro parceiro','A jornada começa com um laço. Escolha um dos Pokémon iniciais de Kanto.',`<div class="starter-grid">${['bulbasaur','charmander','squirtle'].map(k=>`<button class="starter-card" data-starter="${k}">${sprite(k)}<b>${DEX[k].name}</b><small>Pokémon ${DEX[k].type}</small><span class="type-tag">Nº ${String(DEX[k].id).padStart(3,'0')} · KANTO</span></button>`).join('')}</div>`);document.querySelectorAll('[data-starter]').forEach(b=>b.onclick=()=>startGame(b.dataset.starter));$('.close-modal').style.display='none'}
function toast(msg){let t=$('#eventToast');t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2500)}
function gainClue(text){state.quest=Math.min(3,state.quest+1);addJournal(`Pista ${state.quest}/3: ${text}`);toast(`Pista encontrada · ${state.quest}/3`)}
function explore(){if(state.hp<=0){modal('Seu parceiro precisa descansar','A trilha não vai a lugar algum.',`<p class="battle-message">Recupere energia no acampamento antes de continuar.</p>`,`<button class="btn" id="modalRest">Ir ao acampamento</button>`);$('#modalRest').onclick=rest;return}state.explores++;const n=state.explores;$('#scene').classList.add('feed-fade');setTimeout(()=>$('#scene').classList.remove('feed-fade'),500);
 if(state.quest>=3&&!state.bossDefeated){addJournal('Você seguiu as pistas até uma clareira e encontrou o responsável pelas jaulas.');startBattle('rattata',{boss:true});return}
 if(n===1){addJournal('Pegadas estranhas levam a um Pokémon selvagem.');startBattle('pidgey');return}
 if(n===2&&!state.team.some(x=>x.key==='pikachu')){addJournal('Você encontrou uma jaula escondida na mata.');showRescue('pikachu');return}
 if(n===4&&!state.team.some(x=>x.key==='oddish')){addJournal('Um Oddish está preso perto de um riacho.');showRescue('oddish');return}
 if(n===3){let b=Math.random()<.58?'glasses':'berry';if(b==='berry')state.berries+=2;else if(!state.bag.includes(b))state.bag.push(b);state.xp+=12;gainClue('um pedaço de tecido preso às raízes aponta para uma clareira.');levelCheck();save();modal('Pista entre as samambaias','Você encontra marcas de botas e um pequeno suprimento.',`<div class="item-card"><div class="item-art">${ITEMS[b].icon}</div><div><b>${b==='berry'?'Duas bagas Oran':ITEMS[b].name}</b><small>${b==='berry'?'Suprimentos para a jornada.':ITEMS[b].description}</small><small class="move-detail">+12 XP · Uma pista importante para a missão.</small></div></div>`,`<button class="btn" id="continueBtn">Continuar</button>`);$('#continueBtn').onclick=()=>modalRoot.innerHTML='';return}
