function showRescue(key){const p=DEX[key];modal(`Um ${p.name} precisa de ajuda`,`Você encontra o Pokémon preso numa armadilha improvisada.`,`${portrait(key,'equipment-preview')}<p class="battle-message">A armadilha se abre com cuidado. ${p.name} parece assustado, mas decide confiar em você e seguir junto.</p>`,`<button class="btn" id="rescueBtn">Resgatar ${p.name}</button><button class="btn secondary" id="leaveBtn">Continuar trilha</button>`);$('#rescueBtn').onclick=()=>{if(!state.team.some(x=>x.key===key)){state.team.push({key,level:Math.max(1,state.level-1)});addJournal(`${p.name} foi resgatado e entrou para a equipe.`)}modalRoot.innerHTML='';save();toast(`${p.name} agora é seu parceiro!`)};$('#leaveBtn').onclick=()=>modalRoot.innerHTML=''}
function levelCheck(){while(state.xp>=state.level*42){state.xp-=state.level*42;state.level++;state.team.forEach(p=>p.level=Math.max(p.level||1,state.level));state.maxHp=100+(state.level-1)*12+(itemStats(state.active).maxHp||0);state.hp=Math.min(state.maxHp,state.hp+24);addJournal(`Seu parceiro alcançou o nível ${state.level}! Energia máxima aumentada.`);toast(`Nível ${state.level}! +24 de energia`)} }
function availableMoves(key,level){const ids=DEX[key].moves.filter(id=>MOVES[id].level<=level);return ids.length?ids:['struggle']}
function startBattle(key,opts={}){const enemyLevel=opts.boss?Math.max(state.level+1,4):Math.max(1,Math.min(state.level+1,ZONES[state.zone].level+1));battle={key,level:enemyLevel,hp:opts.boss?95+enemyLevel*9:48+enemyLevel*14,maxHp:opts.boss?95+enemyLevel*9:48+enemyLevel*14,boss:!!opts.boss,message:opts.boss?'Um caçador tenta proteger a última jaula. Seu Rattata está pronto para lutar!':`Um ${DEX[key].name} selvagem apareceu! O que ${DEX[state.active].name} fará?`,busy:false};renderBattle()}
function battleBody(){const hero=current(),enemy=battle;const moves=availableMoves(hero.key,state.level);return `<div class="battle-arena"><div class="battle-name"><b>${DEX[hero.key].name}</b><small>Nv. ${state.level} · ${state.hp}/${state.maxHp} energia</small></div><div class="battle-name enemy-name"><b>${battle.boss?'Caçador · ':''}${DEX[enemy.key].name}</b><small>Nv. ${enemy.level} · ${enemy.hp}/${enemy.maxHp} energia</small></div><div class="battle-portrait hero">${portrait(hero.key,'small')}</div><div class="battle-portrait enemy">${sprite(enemy.key)}</div></div><div class="battle-message" id="battleMessage">${battle.message}</div><div class="battle-controls">${moves.map(id=>{const m=MOVES[id];return `<button class="btn" data-move="${id}" ${battle.busy?'disabled':''}><span>${m.name}<small class="move-type"> · ${m.type}</small></span><span class="move-type">POD ${m.power}</span></button>`}).join('')}</div><div class="battle-subcontrols"><button class="btn secondary" id="throwBerry" ${state.berries<1||state.hp>=state.maxHp||battle.busy?'disabled':''}>🫐 Usar Baga Oran (${state.berries})</button><button class="btn secondary" id="fleeBtn" ${battle.boss||battle.busy?'disabled':''}>Recuar</button></div>`}
function renderBattle(){if(!battle)return;modal(battle.boss?'Confronto na clareira':'Encontro selvagem',battle.boss?'Proteja os Pokémon e vença o responsável pelas jaulas.':'Escolha um movimento oficial para agir.',battleBody());document.querySelectorAll('[data-move]').forEach(b=>b.onclick=()=>attack(b.dataset.move));$('#throwBerry').onclick=useBerry;$('#fleeBtn').onclick=fleeBattle}
function damageFor(moveId,attackerLevel,defenderKey,defenderLevel,attackerKey){const m=MOVES[moveId],equip=itemStats(attackerKey);let mod=1;if(m.type==='Fogo'&&DEX[defenderKey].type.includes('Planta'))mod=1.5;if(m.type==='Água'&&DEX[defenderKey].type.includes('Fogo'))mod=1.5;if(m.type==='Planta'&&DEX[defenderKey].type.includes('Água'))mod=1.5;if(m.type==='Fogo'&&DEX[defenderKey].type.includes('Água'))mod=.75;if(m.type==='Água'&&DEX[defenderKey].type.includes('Planta'))mod=.75;if(m.type==='Planta'&&DEX[defenderKey].type.includes('Fogo'))mod=.75;const defense=defenderKey===state.active?itemStats(defenderKey).defense:0;return Math.max(4,Math.floor((((2*attackerLevel/5+2)*m.power/48)+2+equip.attack-defense)*mod*(.88+Math.random()*.24)))}
function attack(moveId){if(!battle||battle.busy)return;battle.busy=true;const hero=current(),m=MOVES[moveId],damage=damageFor(moveId,state.level,battle.key,battle.level,state.active);battle.hp=Math.max(0,battle.hp-damage);battle.message=`${DEX[hero.key].name} usou ${m.name}! Causou ${damage} de dano${battle.hp===0?' e venceu!':''}`;if(battle.hp===0){renderBattle();setTimeout(winBattle,650);return}const enemyMove=availableMoves(battle.key,battle.level)[Math.floor(Math.random()*availableMoves(battle.key,battle.level).length)];const received=damageFor(enemyMove,battle.level,state.active,state.level,battle.key);state.hp=Math.max(0,state.hp-received);battle.message+=` ${DEX[battle.key].name} respondeu com ${MOVES[enemyMove].name} e causou ${received} de dano.`;battle.busy=false;if(state.hp<=0){state.hp=0;battle.message+=' Seu parceiro ficou sem energia.'}renderBattle()}
function winBattle(){if(!battle)return;const defeated=battle;battle=null;const reward=defeated.boss?55:18+defeated.level*6;state.xp+=reward;state.berries+=defeated.boss?5:1;state.hp=Math.min(state.maxHp,state.hp+12);if(defeated.boss){state.bossDefeated=true;state.quest=3;addJournal('O caçador foi derrotado. As jaulas foram abertas e a missão foi concluída!');if(!state.team.some(p=>p.key==='eevee'))state.team.push({key:'eevee',level:Math.max(1,state.level)});}else addJournal(`Você venceu ${DEX[defeated.key].name} e ganhou ${reward} XP.`);levelCheck();save();modal(defeated.boss?'A floresta está livre!':'Vitória na trilha',defeated.boss?'As jaulas foram abertas e os Pokémon estão seguros.':'Seu parceiro venceu o encontro e ganhou experiência.',`<div class="item-card"><div class="item-art">${defeated.boss?'🏅':'✦'}</div><div><b>${defeated.boss?'Missão concluída':'Encontro vencido'}</b><small>+${reward} XP · ${defeated.boss?'+5':' +1'} Baga Oran${defeated.boss?' · Eevee entrou para a equipe.':''}</small></div></div>`,`<button class="btn" id="battleDone">Continuar</button>`);$('#battleDone').onclick=()=>modalRoot.innerHTML=''}
function useBerry(){if(!state.berries||state.hp>=state.maxHp||battle?.busy)return;state.berries--;const healed=Math.min(35,state.maxHp-state.hp);state.hp+=healed;battle.message=`Você usou uma Baga Oran e recuperou ${healed} de energia.`;const key=battle.key,lv=battle.level,remaining=battle.hp,max=battle.maxHp,boss=battle.boss;battle={key,level:lv,hp:remaining,maxHp:max,boss,message:battle.message,busy:false};renderBattle()}
